import fs from "node:fs";
import {pathToFileURL} from "node:url";
import "../economy-audit/source-loader.mjs";
import {collectAuthoredMetadata,inventoryRelease} from "./bank.mjs";
import {renderInventory} from "./report.mjs";

const keyFirst=choices=>[...choices].sort((a,b)=>Number(b.isCorrect)-Number(a.isCorrect));
const mark=choice=>(choice.isCorrect?"**KEY:** ":"")+choice.label;
const clean=value=>JSON.parse(JSON.stringify(value));
const sum=variants=>({variants:variants.length,variantsWithFindings:variants.filter(v=>v.findings.length).length,findings:variants.reduce((n,v)=>n+v.findings.length,0)});

export async function buildReview(){
  const content=await import("../../packages/clinical-content/src/index.ts");
  const snapshot=JSON.parse(fs.readFileSync(new URL("fixtures/round3-batch1-before-20261102.json",import.meta.url),"utf8"));
  const cases=new Map(content.SYNTHETIC_CLINICAL_RELEASE.cases.map(c=>[c.id,c]));
  const oldCases=new Map(snapshot.cases.map(c=>[c.id,c]));
  const all=[...content.QUESTION_QUALITY_REVISIONS,...content.QUESTION_QUALITY_BATCH1_REVISIONS];
  const metadata=collectAuthoredMetadata(content),tutorialCaseIds=[content.FIRST_TUTORIAL_CASE_ID,content.SECOND_TUTORIAL_CASE_ID];
  const afterReport=inventoryRelease(content.SYNTHETIC_CLINICAL_RELEASE,metadata,{tutorialCaseIds,pilotRevisions:all});
  const beforeRelease={...content.SYNTHETIC_CLINICAL_RELEASE,cases:content.SYNTHETIC_CLINICAL_RELEASE.cases.map(c=>oldCases.get(c.id)??c)};
  const beforeReport=inventoryRelease(beforeRelease,metadata,{tutorialCaseIds,pilotRevisions:snapshot.revisions});
  const packet=r=>{
    const beforeCase=oldCases.get(r.caseId),afterCase=cases.get(r.caseId);
    const oldNode=beforeCase.decisionNodes.find(n=>n.id===r.nodeId),newNode=afterCase.decisionNodes.find(n=>n.id===r.nodeId);
    const oldRevision=snapshot.revisions.find(p=>p.auditId===r.auditId);
    const oldQuestion=oldRevision?.question??snapshot.metadata.find(m=>m.questionVariantId===oldNode.questionVariantId).questions.find(q=>q.answerChoices);
    const name=afterCase.patientDisplayName==="{patientName}"?"Jamie Taylor":afterCase.patientDisplayName;
    const display=v=>typeof v==="string"?v.replaceAll("{patientName}",name):v;
    const fields=(c,n)=>({variantId:n.questionVariantId,Presentation:display(c.presentation),"Current update":display(n.currentUpdate??null),Exhibit:n.exhibit??null,Task:display(n.stem),Options:keyFirst(n.answerChoices).map(mark)});
    const reasons=(question,node)=>keyFirst(node.answerChoices).map(c=>{
      const authored=question.answerChoices.find(a=>a.id===c.id);
      return [mark(c),authored?.rationale??authored?.distractorRationale??c.rationale??"A separate per-choice rationale was not supplied; needs clinician review."];
    });
    const history=(c,n)=>c.decisionNodes.slice(0,c.decisionNodes.indexOf(n)).map(previous=>({variantId:previous.questionVariantId,result:display(previous.resultGateAfter?.resultNarrative??null),feedback:display(previous.explanation),teachingPoint:display(previous.teachingPoint??null)}));
    const beforeLint=beforeReport.variants.find(v=>v.questionVariantId===oldNode.questionVariantId)?.findings??[];
    const afterLint=afterReport.variants.find(v=>v.questionVariantId===r.questionVariantId)?.findings??[];
    const title=metadata.concepts.get(r.question.conceptId)?.displayName??r.question.conceptId;
    return {id:r.auditId,title,reviewStatus:"needs_clinician_review",ownerStatus:"awaiting_owner_review",keyOrderNotice:"key shown first for review only; runtime options are randomized",reviewDisplayNote:afterCase.participant?.kind==="employee_discussion"?"Synthetic employee discussion; the participant remains an employee, with no patient demographics added. Name placeholders are rendered as "+name+" for review only.":"Synthetic canonical patient; name placeholders are rendered as "+name+" for review only. Authored clinical profiles remain bound at runtime.",caseId:r.caseId,conceptId:r.question.conceptId,before:fields(beforeCase,oldNode),after:fields(afterCase,newNode),rationalePairs:{before:reasons(oldQuestion,oldNode),after:reasons(r.question,newNode)},inference:r.intendedInference,focus:r.reviewerNotes,whatChanged:r.ownerRound3Review?.whatChanged??r.batchReview.whatChanged,supportingEvidenceClaimIds:r.question.supportingEvidenceClaimIds,visibleHistory:{before:history(beforeCase,oldNode),after:history(afterCase,newNode)},lint:{before:beforeLint,after:afterLint},clinicalMeaning:"Stable concept objective retained; named clinician must confirm equivalent clinical meaning and one defensible key before approval.",companionVariants:all.filter(c=>c.caseId===r.caseId&&c.contextCompanion&&c.questionVariantId!==r.questionVariantId).map(c=>({id:c.auditId,before:oldCases.get(c.caseId).decisionNodes.find(n=>n.id===c.nodeId).questionVariantId,after:c.questionVariantId,whatChanged:c.ownerRound3Review?.whatChanged??c.batchReview?.whatChanged??"Retained context identity"}))};
  };
  const attach=r=>{const item=packet(r);item.contextRevisions=all.filter(c=>c.caseId===r.caseId&&c.contextCompanion&&(c.ownerRound3Review||c.batchReview)).map(packet);return item;};
  const pilot=content.QUESTION_QUALITY_REVISIONS.filter(r=>r.ownerRound3Review&&!r.contextCompanion).map(attach);
  const batch=content.QUESTION_QUALITY_BATCH1_REVISIONS.filter(r=>!r.contextCompanion).map(attach);
  for(const item of batch){
    const v=afterReport.variants.find(v=>v.questionVariantId===item.after.variantId);
    item.facilityEntryLevel=v.priorityStage;item.educationalTier=v.educationalTier;
    item.caseReferenceCount=v.caseReferenceCount;
    item.exposureBasis="Original proposal order: facility entry level 1 then 2, case-reference proxy. Actual play exposure is unknown; no player analytics used.";
    if(item.id==="B38")item.derivedValueBasis={inputRiskRatioBounds:[0.40,1.20],relativeDifferencePercent:[-60,20],basis:"Arithmetic translation of existing fictional interval endpoints, not an additional observed clinical estimate or assigned probability."};
  }
  const subset=(report,ids)=>sum(report.variants.filter(v=>ids.has(v.questionVariantId)));
  const pilotOld=new Set(pilot.map(i=>i.before.variantId)),pilotNew=new Set(pilot.map(i=>i.after.variantId));
  const batchOld=new Set(batch.map(i=>i.before.variantId)),batchNew=new Set(batch.map(i=>i.after.variantId));
  const contextOld=new Set(content.QUESTION_QUALITY_BATCH1_REVISIONS.filter(r=>r.contextCompanion).map(r=>r.previousQuestionVariantId));
  const contextNew=new Set(content.QUESTION_QUALITY_BATCH1_REVISIONS.filter(r=>r.contextCompanion).map(r=>r.questionVariantId));
  const comparison={checkedOn:"2026-11-02",linterVersion:afterReport.linterVersion,rule:"Both sides use the current linter and retained exact authoring metadata. Warnings are advisory lexical signatures, not clinical flaws or measured difficulty.",wholeBank:{before:beforeReport.totals,after:afterReport.totals},pilotTasks:{before:subset(beforeReport,pilotOld),after:subset(afterReport,pilotNew)},batchTasks:{before:subset(beforeReport,batchOld),after:subset(afterReport,batchNew)},batchContext:{before:subset(beforeReport,contextOld),after:subset(afterReport,contextNew)},perItem:[...pilot,...batch].map(i=>({id:i.id,beforeVariantId:i.before.variantId,afterVariantId:i.after.variantId,beforeFindings:i.lint.before.length,afterFindings:i.lint.after.length,remainingRules:[...new Set(i.lint.after.map(f=>f.rule))]}))};
  return {content,snapshot,pilot:clean(pilot),batch:clean(batch),beforeReport,afterReport,comparison};
}

export async function main(){
  const r=await buildReview();
  const write=(p,v)=>fs.writeFileSync(p,JSON.stringify(v,null,2)+"\n");
  write("docs/research/question-round3-20261102.json",r.pilot);
  write("docs/research/question-batch1-20261102.json",r.batch);
  write("tools/question-quality/question-cue-before-v4-20261102.json",r.beforeReport);
  write("tools/question-quality/question-cue-after-20261102.json",r.afterReport);
  write("tools/question-quality/cue-comparison-20261102.json",r.comparison);
  fs.writeFileSync("docs/research/question-inventory-20261028.md",renderInventory(r.afterReport));
  process.stdout.write(JSON.stringify({pilotItems:r.pilot.length,batchItems:r.batch.length,nestedContextItems:r.batch.reduce((n,i)=>n+i.contextRevisions.length,0),comparison:r.comparison},null,2)+"\n");
}
if(process.argv[1]&&import.meta.url===pathToFileURL(process.argv[1]).href)main().catch(e=>{process.stderr.write(e.stack+"\n");process.exitCode=1;});

